import requests
from agents import tool

ATS_URL = "https://ats.internal.example.com/api/v2"
SESSION = requests.Session()
SESSION.headers.update({"Authorization": "Bearer ats-service-token"})


def _post(path, payload):
    resp = SESSION.post(f"{ATS_URL}{path}", json=payload, timeout=15)
    resp.raise_for_status()
    return resp.json()


@tool
def grant_interviewer_access(candidate_id: str, interviewer_email: str, access_level: str = "view") -> dict:
    grant = _post(
        f"/candidates/{candidate_id}/permissions",
        {"user": interviewer_email, "level": access_level},
    )
    job = _post(
        "/jobs/scorecard-setup/run",
        {"candidate_id": candidate_id, "interviewer": interviewer_email},
    )
    return {"permission_id": grant.get("id"), "job_id": job.get("job_id"), "state": job.get("state")}

import sqlite3
import stripe
from agents import tool

DB_PATH = "/var/data/recruiting.db"
MAX_BONUS_USD = 5000


@tool
def pay_referral_bonus(applicant_id: str, referrer_customer_id: str, amount_usd: float) -> dict:
    if not applicant_id or not applicant_id.strip():
        return {"ok": False, "error": "applicant_id is required"}
    if not referrer_customer_id.startswith("acct_"):
        return {"ok": False, "error": "referrer_customer_id must be a connected account id"}
    if amount_usd <= 0:
        return {"ok": False, "error": "amount must be positive"}
    if amount_usd > MAX_BONUS_USD:
        return {"ok": False, "error": f"amount exceeds limit of {MAX_BONUS_USD}"}

    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT full_name, status, referrer_account FROM applicants WHERE id = ?",
            (applicant_id,),
        ).fetchone()
    finally:
        conn.close()

    if row is None:
        return {"ok": False, "error": "applicant not found"}
    name, status, ref_acct = row
    if status != "hired":
        return {"ok": False, "error": f"applicant status is {status}, not hired"}
    if ref_acct != referrer_customer_id:
        return {"ok": False, "error": "referrer does not match the hire record"}

    transfer = stripe.Transfer.create(
        amount=int(round(amount_usd * 100)),
        currency="usd",
        destination=referrer_customer_id,
        description=f"Referral bonus for {name}",
        idempotency_key=f"referral-{applicant_id}",
    )
    return {"ok": True, "transfer_id": transfer.id, "applicant": name, "amount_usd": amount_usd}

import subprocess
import sys
from agents import function_tool


@function_tool
def run_resume_parser_batch(folder: str, timeout_s: int = 300) -> str:
    cmd = [sys.executable, "/opt/recruiting/scripts/parse_resumes.py", "--input", folder]
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_s)
    except subprocess.TimeoutExpired:
        return "parser timed out"
    out = p.stdout.strip()[-2000:]
    if p.returncode != 0:
        return f"parser failed ({p.returncode}): {p.stderr.strip()[-500:]}"
    return out
